const input = $json.body ?? $json;
const text = [input.description, input.voice_note].filter(Boolean).join(' ').trim();
const measurements = input.measurements && typeof input.measurements === 'object' ? input.measurements : {};
const requiredMeasurements = ['length_m', 'height_m'];
const missingMeasurements = requiredMeasurements.filter((key) => !(Number(measurements[key]) > 0));
const questions = [];
if (!input.postcode) questions.push('What is the job postcode?');
if (!input.access_notes) questions.push('Are there access restrictions, steps or parking limits?');
if (missingMeasurements.length) questions.push('Please confirm the required dimensions: ' + missingMeasurements.join(', '));
if (!text) questions.push('Please add a job description or voice-note transcript.');
return [{json:{job_brief:{description:text,postcode:String(input.postcode ?? '').toUpperCase(),photos_received:Array.isArray(input.photo_urls)?input.photo_urls.length:0},estimate_draft:{status:'draft_only',scope_summary:text || 'Not supplied',measurement_values:measurements,measurement_provenance:Object.keys(measurements).map(key=>({field:key,source:'customer_or_contractor_supplied',verified:false})),materials:[],labour:[],assumptions:[],exclusions:[]},missing_information:questions,ready_for_pricing:questions.length===0,approval_gate:'Contractor must verify site conditions, dimensions, quantities, product selection, labour and all prices. No quote is generated or sent by this demo.'}}];
